"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { Slider as BaseSlider } from "@base-ui/react/slider";

import type { StyleXProps } from "../shared/stylex-props.js";
import { styles } from "./slider.stylex.js";

export interface SliderRootProps extends StyleXProps<BaseSlider.Root.Props> {
  "data-visual-state"?: "disabled" | "focus-visible" | "hover" | "pressed" | undefined;
}

export const SliderRoot = React.forwardRef<HTMLDivElement, SliderRootProps>(function SliderRoot(
  { thumbAlignment = "edge", xstyle, ...props },
  ref,
) {
  return (
    <BaseSlider.Root
      {...props}
      className={stylex.props(styles.root, xstyle).className}
      data-slot="slider"
      ref={ref}
      thumbAlignment={thumbAlignment}
    />
  );
});

export const SliderControl = React.forwardRef<
  HTMLDivElement,
  StyleXProps<BaseSlider.Control.Props>
>(function SliderControl({ xstyle, ...props }, ref) {
  return (
    <BaseSlider.Control
      {...props}
      className={stylex.props(styles.control, xstyle).className}
      data-slot="slider-control"
      ref={ref}
    />
  );
});

export const SliderTrack = React.forwardRef<HTMLDivElement, StyleXProps<BaseSlider.Track.Props>>(
  function SliderTrack({ xstyle, ...props }, ref) {
    return (
      <BaseSlider.Track
        {...props}
        className={stylex.props(styles.track, xstyle).className}
        data-slot="slider-track"
        ref={ref}
      />
    );
  },
);

export const SliderIndicator = React.forwardRef<
  HTMLDivElement,
  StyleXProps<BaseSlider.Indicator.Props>
>(function SliderIndicator({ xstyle, ...props }, ref) {
  return (
    <BaseSlider.Indicator
      {...props}
      className={stylex.props(styles.indicator, xstyle).className}
      data-slot="slider-indicator"
      ref={ref}
    />
  );
});

export const SliderThumb = React.forwardRef<HTMLDivElement, StyleXProps<BaseSlider.Thumb.Props>>(
  function SliderThumb({ xstyle, ...props }, ref) {
    return (
      <BaseSlider.Thumb
        {...props}
        className={stylex.props(styles.thumb, xstyle).className}
        data-slot="slider-thumb"
        ref={ref}
      />
    );
  },
);

export const SliderLabel = BaseSlider.Label;
export const SliderValue = BaseSlider.Value;

export const Slider = {
  Control: SliderControl,
  Indicator: SliderIndicator,
  Label: SliderLabel,
  Root: SliderRoot,
  Thumb: SliderThumb,
  Track: SliderTrack,
  Value: SliderValue,
} as const;

import * as stylex from "@stylexjs/stylex";

import { tokens } from "../tokens.stylex.js";

export const sliderState = stylex.defineVars({
  thumbColor: tokens.colorActionPrimary,
  thumbRing: "transparent",
});

export const styles = stylex.create({
  root: {
    [sliderState.thumbColor]: {
      default: tokens.colorActionPrimary,
      ":hover": tokens.colorActionPrimaryHover,
      "[data-dragging]": tokens.colorActionPrimaryHover,
      '[data-visual-state="hover"]': tokens.colorActionPrimaryHover,
      '[data-visual-state="pressed"]': tokens.colorActionPrimaryHover,
    },
    [sliderState.thumbRing]: {
      default: "transparent",
      '[data-visual-state="focus-visible"]': tokens.colorFocusRing,
    },
    boxSizing: "border-box",
    opacity: { default: 1, "[data-disabled]": tokens.opacityDisabled },
    touchAction: "none",
    userSelect: "none",
    width: "100%",
  },
  control: {
    alignItems: "center",
    boxSizing: "border-box",
    cursor: { default: "pointer", "[data-disabled]": "default" },
    display: "flex",
    height: "28px",
    touchAction: "none",
    userSelect: "none",
    width: "100%",
  },
  track: {
    backgroundColor: tokens.colorBorderControl,
    borderRadius: tokens.radiusRounded,
    height: "2px",
    position: "relative",
    userSelect: "none",
    width: "100%",
    "@media (forced-colors: active)": {
      backgroundColor: "GrayText",
      forcedColorAdjust: "none",
    },
  },
  indicator: {
    backgroundColor: tokens.colorActionPrimary,
    borderRadius: tokens.radiusRounded,
    userSelect: "none",
    "@media (forced-colors: active)": {
      backgroundColor: "CanvasText",
      forcedColorAdjust: "none",
    },
  },
  thumb: {
    alignItems: "center",
    backgroundColor: "transparent",
    borderRadius: tokens.radiusRounded,
    boxSizing: "border-box",
    display: "flex",
    height: "28px",
    justifyContent: "center",
    outline: "none",
    userSelect: "none",
    width: "28px",
    "::before": {
      backgroundColor: sliderState.thumbColor,
      borderRadius: tokens.radiusRounded,
      content: "''",
      height: "14px",
      pointerEvents: "none",
      transitionDuration: "80ms",
      transitionProperty: "background-color",
      transitionTimingFunction: "ease-out",
      width: "14px",
      "@media (forced-colors: active)": {
        backgroundColor: "CanvasText",
      },
    },
    "::after": {
      borderColor: sliderState.thumbRing,
      borderRadius: tokens.radiusRounded,
      borderStyle: "solid",
      borderWidth: "2px",
      boxSizing: "border-box",
      content: "''",
      height: "20px",
      pointerEvents: "none",
      position: "absolute",
      width: "20px",
    },
    ":has(input:focus-visible)": {
      [sliderState.thumbRing]: {
        default: tokens.colorFocusRing,
        "@media (forced-colors: active)": "Highlight",
      },
    },
    "@media (forced-colors: active)": {
      forcedColorAdjust: "none",
    },
  },
});

import type * as React from "react";
import type * as stylex from "@stylexjs/stylex";

/**
 * Removes arbitrary class injection from a host module and replaces it with
 * a statically compiled StyleX override. Native inline style remains available
 * for runtime geometry that cannot be known at build time.
 */
export type StyleXProps<Props> = Omit<Props, "className"> & {
  xstyle?: stylex.StyleXStyles;
};

export type StyleXComponentProps<Component extends React.ElementType> = StyleXProps<
  React.ComponentPropsWithRef<Component>
> &
  React.RefAttributes<React.ComponentRef<Component>>;
